use grow_signoz as sdk;

use std::sync::{Arc, Mutex};
use std::time::Duration;

use sdk::core::{Error, ErrorCode};
use sdk::logging::{
    BatchOptions, BatchProcessor, BatchStats, DropPolicy, DropReason, LogExporter, LogRecord,
    Severity,
};
use sdk::testing::logging::MemoryLogExporter;

fn rec(i: usize) -> LogRecord {
    LogRecord::new(Severity::Info, format!("record {i}"))
}

fn processor(exp: &MemoryLogExporter, opts: BatchOptions) -> BatchProcessor {
    BatchProcessor::new(Arc::new(exp.clone()) as Arc<dyn LogExporter>, opts).unwrap()
}

type Drops = Arc<Mutex<Vec<(usize, DropReason)>>>;

fn track_drops(opts: BatchOptions) -> (BatchOptions, Drops) {
    let drops: Drops = Arc::default();
    let d = drops.clone();
    (
        opts.on_drop(move |r, why| d.lock().unwrap().push((r.len(), why))),
        drops,
    )
}

#[test]
fn options_defaults_validation_and_debug() {
    let o = BatchOptions::default();
    assert_eq!(
        (o.max_queue_size, o.max_batch_size, o.max_batch_bytes),
        (2048, 512, 1_048_576)
    );
    assert_eq!(o.flush_interval, Duration::from_secs(1));
    assert_eq!(o.export_timeout, Duration::from_secs(30));
    assert_eq!(o.drop_policy, DropPolicy::DropNewest);
    assert!(o.gzip);
    assert_eq!(
        (o.max_export_retries, o.retry_backoff),
        (2, Duration::from_millis(200))
    );
    assert_eq!(
        BatchOptions::default()
            .retry_backoff(Duration::ZERO)
            .retry_backoff,
        Duration::ZERO
    );
    assert!(o.validate().is_ok());
    for bad in [
        BatchOptions::default().max_queue_size(0),
        BatchOptions::default().max_batch_size(0),
        BatchOptions::default().max_batch_bytes(0),
        BatchOptions::default().flush_interval(Duration::ZERO),
        BatchOptions::default().export_timeout(Duration::ZERO),
    ] {
        assert_eq!(bad.validate().unwrap_err().code(), ErrorCode::Config);
    }
    let dbg = format!("{:?}", BatchOptions::default().on_error(|_, _| {}));
    assert!(dbg.contains("on_error: true"), "{dbg}");
    assert_eq!(DropReason::QueueFull.to_string(), "queue_full");
    assert_eq!(DropReason::Shutdown.as_str(), "shutdown");
    assert_eq!(DropReason::ExportFailed.as_str(), "export_failed");
}

