#[tokio::test]
async fn flush_exports_in_batches_by_count_and_bytes() {
    let exp = MemoryLogExporter::new();
    let p = processor(&exp, BatchOptions::default().max_batch_size(4).gzip(false));
    for i in 0..10 {
        assert!(p.add(rec(i)));
    }
    p.flush(None).await.unwrap();
    assert_eq!(exp.len(), 10);
    let sizes: Vec<usize> = exp.batches().iter().map(|b| b.0).collect();
    assert_eq!(sizes.iter().sum::<usize>(), 10);
    assert!(sizes.iter().all(|s| *s <= 4), "{sizes:?}");
    assert!(
        exp.batches().iter().all(|b| !b.1),
        "gzip flag passed through"
    );
    let s = p.stats();
    assert_eq!(
        s,
        BatchStats {
            queued: 0,
            sent: 10,
            dropped: 0,
            failed: 0,
            retries: 0
        }
    );
    assert!(format!("{p:?}").contains("BatchProcessor"));

    // Byte limit: each record is ~150 bytes, so 300 bytes fit two at most; an oversized record
    // is still sent alone.
    let exp = MemoryLogExporter::new();
    let p = processor(&exp, BatchOptions::default().max_batch_bytes(300));
    for i in 0..5 {
        p.add(rec(i));
    }
    p.add(rec(99).with_attribute("big", "x".repeat(1000)));
    p.flush(Some(Duration::from_secs(5))).await.unwrap();
    assert_eq!(exp.len(), 6);
    assert!(
        exp.batches().iter().all(|b| b.0 <= 2),
        "{:?}",
        exp.batches()
    );
    assert_eq!(exp.batches().last().unwrap().0, 1);
}

