#[tokio::test]
async fn drop_newest_and_drop_oldest() {
    let exp = MemoryLogExporter::new();
    exp.set_delay(Some(Duration::from_millis(50)));
    let (opts, drops) = track_drops(
        BatchOptions::default()
            .max_queue_size(2)
            .flush_interval(Duration::from_secs(60)),
    );
    let p = processor(&exp, opts);
    assert!(p.add(rec(0)));
    assert!(p.add(rec(1)));
    assert!(!p.add(rec(2)));
    assert_eq!(p.stats().dropped, 1);
    assert_eq!(
        drops.lock().unwrap().as_slice(),
        &[(1, DropReason::QueueFull)]
    );
    p.flush(None).await.unwrap();
    assert_eq!(exp.len(), 2);

    let exp = MemoryLogExporter::new();
    let (opts, drops) = track_drops(
        BatchOptions::default()
            .max_queue_size(2)
            .drop_policy(DropPolicy::DropOldest)
            .flush_interval(Duration::from_secs(60)),
    );
    let p = processor(&exp, opts);
    for i in 0..4 {
        assert!(p.add(rec(i)));
    }
    p.flush(None).await.unwrap();
    let bodies: Vec<String> = exp.records().into_iter().map(|r| r.body).collect();
    assert_eq!(bodies, ["record 2", "record 3"]);
    assert_eq!(p.stats().dropped, 2);
    assert_eq!(drops.lock().unwrap().len(), 2);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn block_policy_waits_for_room() {
    let exp = MemoryLogExporter::new();
    exp.set_delay(Some(Duration::from_millis(30)));
    let p = Arc::new(processor(
        &exp,
        BatchOptions::default()
            .max_queue_size(2)
            .max_batch_size(1)
            .drop_policy(DropPolicy::Block)
            .export_timeout(Duration::from_secs(5)),
    ));
    // Sync add from a runtime worker thread blocks (bounded) until the worker makes room.
    for i in 0..6 {
        assert!(p.add(rec(i)), "record {i}");
    }
    // Async add waits without blocking the thread.
    for i in 6..10 {
        assert!(p.add_async(rec(i)).await, "record {i}");
    }
    // Sync add from a plain thread.
    let p2 = p.clone();
    std::thread::spawn(move || assert!(p2.add(rec(10))))
        .join()
        .unwrap();
    p.flush(None).await.unwrap();
    assert_eq!(exp.len(), 11);
    assert_eq!(p.stats().dropped, 0);
}

#[tokio::test]
async fn block_policy_times_out_and_current_thread_fallback() {
    let exp = MemoryLogExporter::new();
    exp.set_delay(Some(Duration::from_secs(5)));
    let p = processor(
        &exp,
        BatchOptions::default()
            .max_queue_size(1)
            .max_batch_size(2)
            .drop_policy(DropPolicy::Block)
            .flush_interval(Duration::from_secs(60))
            .export_timeout(Duration::from_millis(100))
            .max_export_retries(0),
    );
    assert!(p.add(rec(0)));
    // Current-thread runtime: the sync add cannot block and drops instead.
    assert!(!p.add(rec(1)));
    // Async add gives up after export_timeout.
    assert!(!p.add_async(rec(2)).await);
    assert_eq!(p.stats().dropped, 2);
    // Non-block policies take the plain path in add_async.
    let p2 = processor(&MemoryLogExporter::new(), BatchOptions::default());
    assert!(p2.add_async(rec(3)).await);
    p2.shutdown(None).await.unwrap();
    // After shutdown add_async drops with reason shutdown.
    let (opts, drops) = track_drops(BatchOptions::default().drop_policy(DropPolicy::Block));
    let p3 = processor(&MemoryLogExporter::new(), opts);
    p3.shutdown(None).await.unwrap();
    assert!(!p3.add_async(rec(4)).await);
    assert!(!p3.add(rec(5)));
    assert_eq!(
        drops.lock().unwrap().as_slice(),
        &[(1, DropReason::Shutdown), (1, DropReason::Shutdown)]
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn blocked_adds_are_released_by_shutdown() {
    let exp = MemoryLogExporter::new();
    exp.set_delay(Some(Duration::from_millis(300)));
    let p = Arc::new(processor(
        &exp,
        BatchOptions::default()
            .max_queue_size(1)
            .max_batch_size(1)
            .drop_policy(DropPolicy::Block)
            .export_timeout(Duration::from_secs(10)),
    ));
    assert!(p.add(rec(0)));
    tokio::time::sleep(Duration::from_millis(20)).await; // worker takes record 0
    assert!(p.add(rec(1)));
    let blocked = {
        let p = p.clone();
        std::thread::spawn(move || p.add(rec(2)))
    };
    let blocked_async = {
        let p = p.clone();
        tokio::spawn(async move { p.add_async(rec(3)).await })
    };
    tokio::time::sleep(Duration::from_millis(50)).await;
    p.shutdown(Some(Duration::from_secs(5))).await.unwrap();
    assert!(!blocked.join().unwrap());
    assert!(!blocked_async.await.unwrap());
    assert_eq!(exp.len(), 2);
}

#[tokio::test(start_paused = true)]
async fn retryable_failures_are_retried_then_fail() {
    let exp = MemoryLogExporter::new();
    let errors = Arc::new(Mutex::new(Vec::<ErrorCode>::new()));
    let e2 = errors.clone();
    let (opts, drops) = track_drops(
        BatchOptions::default()
            .max_export_retries(2)
            .on_error(move |e, _| e2.lock().unwrap().push(e.code())),
    );
    let p = processor(&exp, opts);
    // Two retryable failures, then success.
    exp.fail_next(Error::unavailable("down"));
    exp.fail_next(Error::timeout("slow"));
    p.add(rec(0));
    p.flush(None).await.unwrap();
    assert_eq!(exp.len(), 1);
    assert_eq!(p.stats().retries, 2);
    assert_eq!(p.stats().failed, 0);

    // Three retryable failures exhaust the retries.
    for _ in 0..3 {
        exp.fail_next(Error::unavailable("down"));
    }
    p.add(rec(1));
    p.flush(None).await.unwrap();
    assert_eq!(p.stats().failed, 1);
    assert_eq!(p.stats().retries, 4);
    assert_eq!(errors.lock().unwrap().as_slice(), &[ErrorCode::Unavailable]);
    assert_eq!(
        drops.lock().unwrap().as_slice(),
        &[(1, DropReason::ExportFailed)]
    );

    // Non-retryable failures fail at once.
    exp.fail_next(Error::validation("bad"));
    p.add(rec(2));
    p.flush(None).await.unwrap();
    assert_eq!(p.stats().failed, 2);
    assert_eq!(p.stats().retries, 4);
}

#[tokio::test]
async fn partial_rejection_and_panicking_callbacks() {
    let exp = MemoryLogExporter::new();
    let seen = Arc::new(Mutex::new(Vec::<String>::new()));
    let s2 = seen.clone();
    let p = processor(
        &exp,
        BatchOptions::default()
            .on_error(move |e, records| {
                s2.lock()
                    .unwrap()
                    .push(format!("{}:{}", e.code(), records.len()));
                panic!("callback panics are contained");
            })
            .on_drop(|_, _| panic!("also contained")),
    );
    exp.reject_next(2);
    for i in 0..5 {
        p.add(rec(i));
    }
    p.flush(None).await.unwrap();
    assert_eq!(exp.len(), 3);
    let s = p.stats();
    assert_eq!((s.sent, s.failed), (3, 2));
    assert_eq!(seen.lock().unwrap().as_slice(), &["VALIDATION:5"]);
    // A drop with a panicking callback is still counted.
    p.shutdown(None).await.unwrap();
    assert!(!p.add(rec(9)));
    assert_eq!(p.stats().dropped, 1);
}

struct Lying;

#[async_trait::async_trait]
impl LogExporter for Lying {
    async fn export(
        &self,
        records: &[LogRecord],
        _: sdk::logging::ExportOptions,
    ) -> sdk::Result<sdk::logging::ExportResult> {
        // Claims fewer accepted records without saying why.
        Ok(sdk::logging::ExportResult::partial(
            records.len() - 1,
            0,
            None,
        ))
    }
}

