#[tokio::test(start_paused = true)]
async fn flush_timeout_and_shutdown_timeout() {
    let exp = MemoryLogExporter::new();
    exp.set_delay(Some(Duration::from_secs(10)));
    let (opts, drops) = track_drops(
        BatchOptions::default()
            .max_batch_size(1)
            .max_export_retries(0),
    );
    let p = processor(&exp, opts);
    p.add(rec(0));
    p.add(rec(1));
    let err = p.flush(Some(Duration::from_millis(50))).await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Timeout);
    assert_eq!(p.stats().queued, 2, "one waiting, one in flight");
    let err = p
        .shutdown(Some(Duration::from_millis(50)))
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Timeout);
    assert_eq!(
        drops.lock().unwrap().as_slice(),
        &[(2, DropReason::Shutdown)]
    );
    assert_eq!(p.stats().queued, 0);
    assert_eq!(exp.shutdown_calls(), 1);
    // Idempotent; flush after shutdown returns at once.
    p.shutdown(None).await.unwrap();
    p.flush(None).await.unwrap();
    assert_eq!(exp.shutdown_calls(), 1);
}

